var NOMI_ALIAS={'vitello':'Vitiello','vitale':'Vitale'};
function fixName(p){ var k=(p||'').trim().toLowerCase(); return NOMI_ALIAS[k] || (p||'').trim(); }
function fixWeek(w){ if(w && w.giorni) w.giorni.forEach(function(g){ g.turni.forEach(function(t){ t.attivita.forEach(function(a){ var seen={}; a.persone=(a.persone||[]).map(fixName).filter(function(p){ if(seen[p]) return false; seen[p]=1; return true; }); }); }); }); return w; }
